create table public.food_vendors(id uuid primary key default gen_random_uuid(),campus_id uuid not null references public.campuses(id) on delete restrict,manager_id uuid references public.profiles(id) on delete set null,name text not null,contact text,status text not null default 'active',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(campus_id,name));
create table public.food_menu_categories(id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.food_vendors(id) on delete restrict,name text not null,position smallint not null default 0,is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(vendor_id,name));
create table public.food_menu_items(id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.food_vendors(id) on delete restrict,category_id uuid references public.food_menu_categories(id) on delete set null,name text not null,description text not null default '',price numeric(14,2) not null,currency char(3) not null default 'INR',media_asset_id uuid references public.media_assets(id) on delete set null,is_available boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint food_price check(price>=0));
create table public.food_orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id) on delete restrict,vendor_id uuid not null references public.food_vendors(id) on delete restrict,fulfillment_type text not null,delivery_location text,total_amount numeric(14,2) not null default 0,currency char(3) not null default 'INR',order_status text not null default 'draft',payment_status text not null default 'pending',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint food_total check(total_amount>=0));
create table public.food_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.food_orders(id) on delete cascade,menu_item_id uuid references public.food_menu_items(id) on delete set null,title_snapshot text not null,unit_price numeric(14,2) not null,quantity integer not null,line_total numeric(14,2) not null,created_at timestamptz not null default timezone('utc',now()),constraint food_item_amounts check(unit_price>=0 and quantity>0 and line_total>=0));
create table public.food_order_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.food_orders(id) on delete restrict,actor_id uuid references public.profiles(id) on delete set null,status text not null,note text not null default '',created_at timestamptz not null default timezone('utc',now()));
create index food_orders_buyer_idx on public.food_orders(buyer_id,created_at desc);create index food_orders_vendor_idx on public.food_orders(vendor_id,order_status,created_at desc);alter table public.food_vendors enable row level security;alter table public.food_menu_categories enable row level security;alter table public.food_menu_items enable row level security;alter table public.food_orders enable row level security;alter table public.food_order_items enable row level security;alter table public.food_order_events enable row level security;
create policy vendors_read on public.food_vendors for select to authenticated using(status='active' or manager_id=auth.uid());create policy vendors_manage on public.food_vendors for all to authenticated using(manager_id=auth.uid() or public.has_permission('food.manage',campus_id)) with check(manager_id=auth.uid() or public.has_permission('food.manage',campus_id));create policy menu_categories_read on public.food_menu_categories for select to authenticated using(true);create policy menu_categories_manage on public.food_menu_categories for all to authenticated using(exists(select 1 from public.food_vendors v where v.id=vendor_id and v.manager_id=auth.uid())) with check(exists(select 1 from public.food_vendors v where v.id=vendor_id and v.manager_id=auth.uid()));create policy menu_items_read on public.food_menu_items for select to authenticated using(is_available);create policy menu_items_manage on public.food_menu_items for all to authenticated using(exists(select 1 from public.food_vendors v where v.id=vendor_id and v.manager_id=auth.uid())) with check(exists(select 1 from public.food_vendors v where v.id=vendor_id and v.manager_id=auth.uid()));create policy orders_read on public.food_orders for select to authenticated using(buyer_id=auth.uid() or exists(select 1 from public.food_vendors v where v.id=vendor_id and v.manager_id=auth.uid()));create policy orders_insert on public.food_orders for insert to authenticated with check(buyer_id=auth.uid());create policy order_items_read on public.food_order_items for select to authenticated using(exists(select 1 from public.food_orders o where o.id=order_id and o.buyer_id=auth.uid()));create policy order_items_insert on public.food_order_items for insert to authenticated with check(exists(select 1 from public.food_orders o where o.id=order_id and o.buyer_id=auth.uid() and o.order_status='draft'));create policy order_events_read on public.food_order_events for select to authenticated using(exists(select 1 from public.food_orders o where o.id=order_id and o.buyer_id=auth.uid()));
